  "firstMeeting.terisa": "要是哪裡破了……我幫你縫好，小傢伙。",
  "firstMeeting.parua": "好遠……好遠啊！全都看得見。",
  "firstMeeting.shute": "我說了不是那個！照我的指示來。",
  "firstMeeting.morphe": "全部放出去吧。我就在這裡看著。",
  "firstMeeting.dian": "我會保護你的，隊長！……啊，克羅！希羅！",
