  "city.doppel-parlor.description": "多佩爾中央研究所一側的會客室。客人入座後，研究日誌會一頁一頁遞過來。",
  "city.doppel-lab.description": "位於多佩爾研究所深處的內部研究機構。曾被派往以太納的研究員們留下的日記彙集於此。",
  "city.doppel-lab.displayName": "多佩爾 · 內部研究機構",
  "city.doppel-office.description": "彙總研究成果與遺物用途的多佩爾管理部。審批要經過層層關卡，需要等很久。",
  "city.doppel-office.displayName": "多佩爾 · 管理部",
  "city.rust-garage.description": "拉斯特的維修場。請求修理損壞研究裝置的委託接連不斷。",
  "city.rust-garage.displayName": "拉斯特 · 維修場",
  "city.rust-lease.description": "出租高效能裝置的拉斯特租賃管理部。就連一次續租也要經過漫長的談判。",
  "city.rust-lease.displayName": "拉斯特 · 租賃管理部",
  "city.doppel-upper.description": "多佩爾研究所的最高層。決定研究目的的人坐在這裡。",
  "city.doppel-upper.displayName": "多佩爾 · 上層部",
  "city.rust-works.description": "矗立在拉斯特中心的巨大工坊。研究裝置的設計與維修都匯聚於此。",
  "city.rust-works.displayName": "拉斯特 · 中央工坊",
  "city.odidi-embassy.description": "研究夢境的都市奧迪迪迎接外來賓客的接見室。提議總是由他們先開口。",
  "city.odidi-embassy.displayName": "奧迪迪 · 外交接見室",
