  "shopClerk.protia.name": "普羅緹婭",
  "shopClerk.haine.name": "海涅",
  "journal.interaction-doppel-01.title": "藍色走廊的告示牌",
  "journal.interaction-doppel-01.body": "溫室的第一塊告示牌上，仍寫著請將復原體當作新鄰居而非展覽品來歡迎。",
  "journal.interaction-doppel-02.title": "重複的問候",
  "bond.torika.0": "你是誰？",
  "bond.torika.1": "你又來了。",
  "bond.torika.2": "可以待在我身邊。",
  "bond.torika.3": "今天要做什麼呢？",
  "bond.torika.4": "我認得你的腳步聲。",
  "bond.torika.5": "和你在一起，心裡很平靜。",
  "bond.torika.6": "你的背後交給我。",
  "bond.torika.7": "我一直在等你。",
  "bond.torika.8": "你來了我就安心。",
  "bond.torika.9": "我會陪你走到最後。",
  "bond.torika.10": "我們的庭園，由我來守護。",
  "bond.rex.0": "別碰我。",
  "bond.rex.1": "不怕嗎？",
  "bond.rex.2": "有點意思。",
  "bond.rex.3": "下次狩獵也來吧。",
  "bond.rex.4": "我記住你的氣味了。",
  "bond.rex.5": "別離開我身邊。",
  "bond.rex.6": "衝你來的，我全咬回去。",
  "bond.rex.7": "今天又遲到了。",
  "bond.rex.8": "比起命令，我更喜歡你的聲音。",
  "bond.rex.9": "你是我唯一的族群。",
  "bond.rex.10": "我會永遠站在你這邊。",
  "bond.spino.0": "……什麼事？",
  "bond.spino.1": "好想念水啊。",
  "bond.spino.2": "安靜待著也沒關係。",
  "bond.spino.3": "再多講講你的事吧。",
  "bond.spino.4": "今天的浪很平靜。",
  "bond.spino.5": "我喜歡一起散步。",
  "bond.spino.6": "危險的話就躲到我身後。",
  "bond.spino.7": "我就知道你會來。",
  "bond.spino.8": "我已經習慣這座城市了。",
  "bond.spino.9": "你的身邊就是我的水。",
  "bond.spino.10": "一起流向任何地方吧。",
  "bond.generic.0": "還是有點陌生。",
  "bond.generic.1": "今天又見面了。",
  "bond.generic.2": "正一點一點習慣。",
  "bond.generic.3": "一起去執行任務吧。",
  "bond.generic.4": "你來了我很高興。",
  "bond.generic.5": "可以待在我身邊。",
  "bond.generic.6": "這次也會幫忙的。",
  "bond.generic.7": "我一直在等你。",
  "bond.generic.8": "我們是好夥伴。",
  "bond.generic.9": "想和你一直在一起。",
  "bond.generic.10": "今後也拜託你了。",
