  "relic.raitia-grass.origin": "睡鼠",
  "relic.raitia-grass.excavationSite": "斯洛維尼亞 喀斯特洞穴沉積層",
  "relic.raitia-grass.fossilRecord": "從洞穴沉積物的同一層中回收了數十個同種頭骨。其中五個在大小與齒列上高度一致，被歸為同一窩。",
  "relic.raitia-grass.catalogSummary": "以睡鼠為基礎，復原出過大門齒與頰囊的個體。",
  "relic.raitia-grass.squadNote": "殲滅的消耗性兵力。她們朝指向的方向一齊湧去填滿走廊，後面的直接踏過前面倒下的地方。",
  "relic.raitia-grass.researcherTitle": "研究員",
  "relic.raitia-grass.unlockRecord": "識別記錄207。已確認隸屬於殲滅。在五個穿著帶鼠耳兜帽睡衣的個體中，這隻繫著綠色繩結，乳酪形小包、帶牙齒的拖鞋以及末端繫著緞帶的條紋尾巴格外顯眼。找到食物時，它不是用叫聲而是用門齒的聲音傳訊，聽到的姐妹們一齊湧向同一處。它啃過的地方散落著新芽，走過的路上每個腳印都長出種子的嫩芽，留下一條綠色的道路。到了該冬眠的時候仍不停止進食的原因，尚未確認。",
  "relic.raitia-grass.observation.originYear": "約200萬年前",
  "relic.raitia-grass.observation.restorationYear": "E.C. 2",
  "relic.raitia-grass.observation.lifeStage": "幼年",
  "relic.raitia-grass.observation.height": "0.94 m",
  "relic.raitia-grass.observation.weight": "21 kg",
  "relic.raitia-grass.passive.name": "冬眠",
  "relic.raitia-grass.passive.desc": "每場戰鬥一次，生命降至一半以下時，5秒內每秒恢復最大生命的3%。",
  "relic.raitia-grass.ferocity.name": "暴食",
  "relic.raitia-grass.basic.name": "門齒啃咬",
  "relic.raitia-grass.ultimate.name": "頰囊傾倒",
  "relic.raitia-grass.projectName": "ANNIHILATION SWARM — 過食個體群",
  "relic.raitia-water.name": "古緹婭",
