  "relic.raitia-water.excavationSite": "斯洛維尼亞 喀斯特洞穴沉積層",
  "relic.raitia-water.fossilRecord": "從洞穴沉積物的同一層中回收了數十個同種頭骨。其中五個在大小與齒列上高度一致，被歸為同一窩。",
  "relic.raitia-water.catalogSummary": "以睡鼠為基礎，復原出過大門齒與頰囊的個體。",
  "relic.raitia-water.squadNote": "殲滅的消耗性兵力。她們朝指向的方向一齊湧去填滿走廊，後面的直接踏過前面倒下的地方。",
  "relic.raitia-water.researcherTitle": "研究員",
  "relic.raitia-water.unlockRecord": "識別記錄208。已確認隸屬於殲滅。在同樣的帶兜帽睡衣中，這隻的藍色條紋尾巴末端繫著棉球，一隻手叉腰，另一隻手的手指抵在嘴邊微笑。聽到姐妹的門齒聲時，它笑著第一個衝出來，靠近後先用門齒啃手邊夠得著的裝備。群體走過的地方留下了長長的溼腳印。是什麼打溼了那些腳印，尚未確認。",
  "relic.raitia-water.observation.originYear": "約200萬年前",
  "relic.raitia-water.observation.restorationYear": "E.C. 2",
