  "relic.raitia-fire.excavationSite": "斯洛維尼亞 喀斯特洞穴沉積層",
  "relic.raitia-fire.fossilRecord": "從洞穴沉積物的同一層中回收了數十個同種頭骨。其中五個在大小與齒列上高度一致，被歸為同一窩。",
  "relic.raitia-fire.catalogSummary": "以睡鼠為基礎，復原出過大門齒與頰囊的個體。",
  "relic.raitia-fire.squadNote": "殲滅的消耗性兵力。她們朝指向的方向一齊湧去填滿走廊，後面的直接踏過前面倒下的地方。",
  "relic.raitia-fire.researcherTitle": "研究員",
  "relic.raitia-fire.unlockRecord": "識別記錄209。已確認隸屬於殲滅。在同樣的帶兜帽睡衣中，這隻戴著粉色格紋緞帶，帶著沒睡醒的臉站著，一隻手揉眼睛，另一隻手叉腰。儘管一臉睏意，它也沒有停止進食，頰囊塞滿之後仍用門齒啃個不停。姐妹們湧過去時，它揉著眼睛跟在後面。這份睏倦是裝的還是真的，尚未確認。",
  "relic.raitia-fire.observation.originYear": "約200萬年前",
  "relic.raitia-fire.observation.restorationYear": "E.C. 2",
