  "relic.raitia-earth.fossilRecord": "從洞穴沉積物的同一層中回收了數十個同種頭骨。其中五個在大小與齒列上高度一致，被歸為同一窩。",
  "relic.raitia-earth.catalogSummary": "以睡鼠為基礎，復原出過大門齒與頰囊的個體。",
  "relic.raitia-earth.squadNote": "殲滅的消耗性兵力。她們朝指向的方向一齊湧去填滿走廊，後面的直接踏過前面倒下的地方。",
  "relic.raitia-earth.researcherTitle": "研究員",
  "relic.raitia-earth.unlockRecord": "識別記錄210。已確認隸屬於殲滅。在同樣的帶兜帽睡衣中，這隻以棕色底色、黃色繩結和麻花辮最為顯眼，尾巴末端掛著一大團毛球。它向前伸出手站立時，姐妹們會一齊朝著它指尖的方向湧去，前面的個體倒下的地方，後面的個體直接踩過去。是誰決定了它指尖所指的方向，尚未確認。",
  "relic.raitia-earth.observation.originYear": "約200萬年前",
