  "relic.raitia-wind.catalogSummary": "以睡鼠為基礎，復原出過大門齒與頰囊的個體。",
  "relic.raitia-wind.squadNote": "殲滅的消耗性兵力。她們朝指向的方向一齊湧去填滿走廊，後面的直接踏過前面倒下的地方。",
  "relic.raitia-wind.researcherTitle": "研究員",
  "relic.raitia-wind.unlockRecord": "識別記錄211。確認隸屬於殲滅。是同樣穿著連帽睡衣的姐妹中繫著薄荷色絲帶的個體，抱著胳膊、緊閉著嘴站著。直到姐妹們湧向食物之後，她才勉強跟了過去，到了之後卻是啃動門齒最久的一個。從未觀察到她用門齒的聲音傳達過任何資訊。",
